const raw = $input.first()?.json || {};
const statusCode = raw.statusCode || 0;
const body = raw.body || raw;

if (!body.available || !body.attack || !body.should_alert || !$env.ALERT_WEBHOOK_URL) {
  return [];
}

const fmtTime = (value) => {
  if (!value) return '无';
  const numeric = Number(value);
  const millis = Number.isFinite(numeric) ? (numeric < 1e12 ? numeric * 1000 : numeric) : Date.parse(String(value));
  const date = new Date(millis);
  return Number.isNaN(date.getTime()) ? String(value) : date.toISOString();
};

const topIps = Array.isArray(body.top_ips) && body.top_ips.length
  ? body.top_ips.slice(0, 5).map((item) => `${item.ip}（${item.count} 次）`).join('、')
  : '无';
const byType = body.by_type && typeof body.by_type === 'object'
  ? Object.entries(body.by_type).map(([type, count]) => `${type} ${count}`).join('、') || '无'
  : '无';
const recentLines = Array.isArray(body.recent) && body.recent.length
  ? body.recent.slice(0, 3).map((event) => `${fmtTime(event.at)} ${event.type || ''} ${event.ip || ''}`.trim())
  : [`最近一次：${fmtTime(body.last_event_at)}`];

const fallback = [
  'CokeAI 安全攻击告警',
  `近 ${body.window_minutes ?? '—'} 分钟拦截：${body.window_count ?? '—'} 次（阈值 ${body.threshold ?? '—'}）`,
  `今日拦截：${body.today_total ?? '—'} 次，独立 IP：${body.today_unique_ips ?? '—'}`,
  `Top IP：${topIps}`,
  `类型分布：${byType}`,
  '最近事件：',
  ...recentLines,
  '后台：/admin/security',
  `时间：${fmtTime(body.generated_at) || new Date().toISOString()}`,
].join('\n');

const text = body.alert_text || fallback;

return [{ json: { text, content: text, source: 'cokeai-security', attack: true } }];
